-- OBSIDIANKNIGHTRPG(A!U)[32+64]-V22.01_VI
-- Do not edit this file. Any change breaks the decoder.
local _crcwub = 74
local _vhpnjo = 68
local _pkdfqw = 139
local _vgentq = ""

local _gviqmi = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _rxjsys(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _tpdcnq(d)
	d = d:gsub("[^" .. _gviqmi .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_gviqmi:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _twuusk = _tpdcnq(_vgentq)
local _mwahhx = { _crcwub, _vhpnjo, _pkdfqw }
local _loolge = {}
for i = 1, #_twuusk do
	_loolge[i] = string.char(_rxjsys(_twuusk:byte(i), _mwahhx[(i - 1) % 3 + 1]))
end

local _qtiiky = load or loadstring
local _layklz, _qsjadt = _qtiiky(table.concat(_loolge), "=w")
if not _layklz then
	gg.alert("Corrupted file: " .. tostring(_qsjadt))
	os.exit()
end
_layklz()
